function degToRad(degrees:number):number {
  return degrees * (Math.PI / 180);
}


function radToDeg(radian:number):number {
  return radian * (180/Math.PI);
}




function azimuthalEquidistantProjection(pt:LatLng, lat0=48.8566, lon0 = 2.3522, radius= 6371000) {
  // Convert degrees to radians
  const latRad = pt.lat * Math.PI / 180;
  const lonRad = pt.lng * Math.PI / 180;
  const lat0Rad = lat0 * Math.PI / 180;
  const lon0Rad = lon0 * Math.PI / 180;

  // Calculate differences
  const dLon = lonRad - lon0Rad;

  // Calculate great circle distance
  const centralAngle = Math.acos(Math.sin(lat0Rad) * Math.sin(latRad) + Math.cos(lat0Rad) * Math.cos(latRad) * Math.cos(dLon));

  // Azimuthal equidistant projection formulas
  const x = radius * centralAngle * Math.cos(latRad) * Math.sin(dLon);
  const y = radius * centralAngle * (Math.cos(lat0Rad) * Math.sin(latRad) - Math.sin(lat0Rad) * Math.cos(latRad) * Math.cos(dLon));

  return new Point(x,y);
}



export function polarToCartesian(polar:LatLng,scale:number=1,translate=0,radius:number = 6371000): Point3D {
  if(!polar)return new Point3D(0,0,0)
  const latRad = degToRad(polar.lat);
  const lonRad = degToRad(polar.lng);

  const x = radius * Math.cos(latRad) * Math.cos(lonRad)*scale;
  const y = radius * Math.cos(latRad) * Math.sin(lonRad)*scale;
  const z = radius * Math.sin(latRad) * scale;

  return new Point3D(Math.round(x)+translate, Math.round(y)+translate, Math.round(z)+translate )
}


export function center_of(pt1:Point3D,pt2:Point3D) : Point3D {
  return new Point3D((pt2.x+pt1.x)/2,(pt2.y+pt1.y)/2,(pt2.z+pt1.z)/2)
}



export function cartesianToPolar(pt:Point3D,scale:number=1,translate=0) : LatLng {
  const xx=(pt.x-translate)/scale
  const yy=(pt.y-translate)/scale
  const zz=(pt.z-translate)/scale
  const r = Math.sqrt(xx * xx + yy * yy + zz * zz);
  const theta = Math.acos(zz / r);
  const phi = Math.atan2(yy, xx);

  return new LatLng(90-radToDeg(theta),radToDeg(phi));
}




export function distance(p1:LatLng, p2:LatLng,R=6371000): number {
  //Rayon de la terre en metres
  const dLat = degToRad(p2.lat - p1.lat);
  const dLon = degToRad(p2.lng- p1.lng);

  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(degToRad(p1.lat)) * Math.cos(degToRad(p2.lat)) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  return R*c;
}


export function add_icon(map:any,icon:string,pos:LatLng=new LatLng(0,0),
                         title="me",size=30){
  if(icon=='')return null
  return L.marker(pos,{
    icon:L.icon({
      iconUrl: icon,
      iconSize: [size, size], // size of the icon
      iconAnchor: [size/2, size/2], // point of the icon which will correspond to marker's location
    }),
    alt:title
  }).addTo(map)
}



export async function hashMessage(message: string) {
  const encoder = new TextEncoder();
  const data = encoder.encode(message);
  const hash = await crypto.subtle.digest('SHA-256', data);
  return hash;
}


export function add_entrance_and_exit(vm:any,zone:any,entranceIcon="https://tokemon.f80.fr/assets/icons/flag_24dp_5F6368.png",
                                      exitIcon="https://tokemon.f80.fr/assets/icons/flag.png") {

  $$("Ajout de l'entree et la sortie")
  if(zone.entrance && zone.entrance.x+zone.entrance.y+zone.entrance.z!=0){
    let entrance=cartesianToPolar(zone.entrance,environment.scale_factor,environment.translate_factor)
    $$("entrance ajouté en ",entrance)
    add_icon(vm.map,entranceIcon,entrance)
  }
  if(zone.exit && zone.exit.x+zone.exit.y+zone.exit.z!=0){
    let exit=cartesianToPolar(zone.exit,environment.scale_factor,environment.translate_factor)
    add_icon(vm.map,exitIcon,exit)
    $$("exit ajouté en ",exit)
  }
}



export function initializeMap(vm:any,zone:any,
                              center:LatLng=new LatLng(0,0),
                              centerIcon='https://tokemon.f80.fr/assets/icons/person_24dp_5F6368.png',
                              entranceIcon="https://tokemon.f80.fr/assets/icons/entrance.png",
                              exitIcon="https://tokemon.f80.fr/assets/icons/exit.png") : L.Map {

  if(vm.map && zone){
    if(zone.url=="map" || zone.url=="")zone.zoom=2;

    L.tileLayer(baseMapURl).addTo(vm.map);
    L.tileLayer(baseMapURl, {attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(vm.map).redraw()

    if(centerIcon.length>0){
      vm.me_marker=add_icon(vm.map,centerIcon,center)
      vm.me_marker.removeFrom(vm.map)
    }

    add_entrance_and_exit(vm,zone,entranceIcon,exitIcon)

  }
  return vm.map
}



export function share_game(vm:any,game: any,default_message="",
                           share_menu=true,ask_message=true) : Promise<{shorturl:string}> {
  return new Promise(async (resolve) => {
    let message=default_message
    if(vm.hasOwnProperty("dialog") && ask_message)message = await _prompt(vm, "Write an introduction message for the players", default_message, "", "memo", "Share", "Cancel", false)
    let params = {autoconnect: true, game: game.id, message: message}
    $$("Demande de raccourcissement de https://localhost:4200/intro/?" + setParams(params))

    let short_url =await url_shorter( settings.appli + "/?" + setParams(params))
    if(vm.hasOwnProperty("shareService") && share_menu){
      await vm.shareService.share({
        title: "Join me in "+game.title+" gaming zone",
        text: message,
        url: short_url
      })
    }
    if(vm.hasOwnProperty("clipboard")){
      vm.clipboard.copy(short_url)
      showMessage(vm, "Link in clipboard")
    }
    resolve({shorturl:short_url})

  })

}


export function url_shorter(url_to_short:string) : Promise<string> {
  return new Promise(async (resolve, reject) => {
    let url="https://is.gd/create.php?format=json&url="+encodeURIComponent(url_to_short)
    let r=await fetch(url,{mode:'cors'});
    let resp:any=await r.json()
    $$("Récupération de l'url de partage de la game ",resp)
    resolve(resp.shorturl);
    })
}

//tag in_the_game in_game
export function is_in(pt:LatLng,zone:Game) : boolean {
  let ne=cartesianToPolar(zone.ne,environment.scale_factor,environment.translate_factor)
  let sw=cartesianToPolar(zone.sw,environment.scale_factor,environment.translate_factor)

  return pt.lat>Math.min(ne.lat,sw.lat) && pt.lng>Math.min(ne.lng,sw.lng) && pt.lat<Math.max(ne.lat,sw.lat) && pt.lng<Math.max(ne.lng,sw.lng)
}
