import {AfterViewInit, Component, inject, OnInit} from '@angular/core';
import {ActivatedRoute, Router, RouterOutlet} from '@angular/router';
import {MatToolbar} from '@angular/material/toolbar';
import {MatDialog} from '@angular/material/dialog';
import {environment} from "../environments/environment";
import {UserService} from './user.service';
import {$$, getParams, setParams} from '../tools';
import {MatIcon} from '@angular/material/icon';
import {MatButton, MatIconButton} from '@angular/material/button';
import {DecimalPipe, NgIf} from '@angular/common';
import {MatSnackBar} from '@angular/material/snack-bar';
import {MapComponent} from './map/map.component';
import {MatCheckbox} from '@angular/material/checkbox';
import {MatSlideToggle} from '@angular/material/slide-toggle';
import {FormsModule} from '@angular/forms';
import {InputComponent} from './input/input.component';
import {ApiService} from './api.service';
import {share_game} from './tokenworld';
import {NgNavigatorShareService} from 'ng-navigator-share';
import {level} from './mvx';


@Component({
  selector: 'app-root',
  standalone: true,
  imports: [RouterOutlet, MatToolbar, MatIcon, MatIconButton, NgIf, MapComponent, DecimalPipe, MatButton, MatCheckbox, MatSlideToggle, FormsModule, InputComponent],
  templateUrl: './app.component.html',
  styleUrl: './app.component.css'
})
export class AppComponent implements OnInit {


  title = 'tokemonworld';
  router=inject(Router)
  dialog=inject(MatDialog)
  user=inject(UserService)
  routes=inject(ActivatedRoute)
  toast=inject(MatSnackBar)
  api=inject(ApiService)
  shareService=inject(NgNavigatorShareService)


  logout() {
    this.user.logout()
  }



  async login() {
    await this.user.login(this,"","",true)
    localStorage.setItem("address",this.user.address)
    this.show_intro=false
  }





  async ngOnInit() {
    this.user.expert_mode=(localStorage.getItem("expert_mode") || "false")=="true"

    // if (typeof Worker !== 'undefined') {
    //   // Create a new
    //   const worker = new Worker(new URL('./app.worker', import.meta.url));
    //   worker.onmessage = ({ data }) => {
    //     console.log(`page got message: ${data}`);
    //   };
    //   worker.postMessage('hello');
    // } else {
    //   // Web workers are not supported in this environment.
    //   // You should add a fallback so that your program still executes correctly.
    // }
  }


  protected readonly environment = environment;
  show_intro=true
  message: string=""


  test() {
    this.router.navigate(["test"])
  }

  open_map() {
    this.router.navigate(["map"])
  }


  go_settings() {
    this.router.navigate(["settings"])
  }

  go_admin() {
    this.router.navigate(["admin"])
  }



  create_world() {
    let zoom=Math.round(Math.max(this.user.zoom*2,16))
    this.router.navigate(["create"],
      {
        queryParams:{p: setParams({
            lat:this.user.center_map.lat,
            lng:this.user.center_map.lng,
            zoom:zoom},"","")}
      })
  }


  open_games() {
    this.user.game=undefined
    this.router.navigate(["games"],{queryParams:{autoconnect:false}})
  }

  go_mytokemons() {
    this.router.navigate(["mytokemons"])
  }

  share_game(){
    share_game(this,this.user.game,"Find NFT in this game zone")
  }

  go_about() {
    this.router.navigate(["about"])
  }

  protected readonly level = level;
}
